//! End-to-end test for the ONNX detection backend: runs a tiny Identity
//! fixture (`pred_in[1,anchors,7] -> pred[1,anchors,7]`) through
//! `OnnxDetectBackend`, so the assertions cover the real session-run ->
//! score/threshold/NMS wiring against exact expected detections (the unit tests
//! cover the decoder on synthetic packets).
//!
//! The fixture is generated by `tests/fixtures/make_identity_detect.py`. Its 7
//! channels are `cx, cy, w, h, objectness, class0, class1`, so the identity
//! output is whatever prediction grid the test feeds in.

use kapsl_backends::onnx::ExecutionProvider;
use kapsl_backends::onnx_detect::DetectConfig;
use kapsl_backends::{OnnxBackend, OnnxDetectBackend};
use kapsl_engine_api::{BinaryTensorPacket, Engine, InferenceRequest, TensorDtype};
use std::path::PathBuf;

fn f32_packet(shape: Vec<i64>, vals: &[f32]) -> BinaryTensorPacket {
    let mut data = Vec::new();
    for v in vals {
        data.extend_from_slice(&v.to_le_bytes());
    }
    BinaryTensorPacket {
        shape,
        dtype: TensorDtype::Float32,
        data,
    }
}

fn to_f32(p: &BinaryTensorPacket) -> Vec<f32> {
    p.data
        .as_chunks::<4>()
        .0
        .iter()
        .map(|b| f32::from_le_bytes(*b))
        .collect()
}

fn config(class_agnostic: bool) -> DetectConfig {
    serde_yaml::from_str(&format!(
        "num_classes: 2\nscore_threshold: 0.25\niou_threshold: 0.45\n\
         box_format: xywh\nobjectness: true\nclass_agnostic: {class_agnostic}"
    ))
    .expect("detect config")
}

/// Six anchors, channels `[cx, cy, w, h, obj, c0, c1]`:
/// - A: class 0, score 0.9*0.9 = 0.81, box (75,75,125,125)
/// - B: class 0, score 0.72, nearly on top of A (IoU 0.85) -> suppressed by A
/// - C: same box as B but class 1, score 0.72 -> survives per-class NMS
/// - D: best score 0.5*0.2 = 0.10, below the 0.25 threshold -> dropped
/// - E: class 0, score 0.6*0.8 = 0.48, far from the others
/// - F: class 1, score 1.0*0.5 = 0.50, far from the others
const GRID: [f32; 42] = [
    100.0, 100.0, 50.0, 50.0, 0.9, 0.9, 0.1, // A
    104.0, 100.0, 50.0, 50.0, 0.8, 0.9, 0.1, // B
    104.0, 100.0, 50.0, 50.0, 0.8, 0.1, 0.9, // C
    300.0, 300.0, 40.0, 60.0, 0.5, 0.1, 0.2, // D
    200.0, 50.0, 20.0, 20.0, 0.6, 0.8, 0.3, // E
    10.0, 10.0, 8.0, 8.0, 1.0, 0.0, 0.5, // F
];

async fn run(class_agnostic: bool) -> BinaryTensorPacket {
    let model =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/identity_detect.onnx");

    let mut inner = OnnxBackend::builder()
        .with_provider(ExecutionProvider::CPU)
        .build();
    inner.load(&model).await.expect("load detect fixture");
    let backend = OnnxDetectBackend::new(Box::new(inner), config(class_agnostic)).expect("detect");

    let req = InferenceRequest::new(f32_packet(vec![1, 6, 7], &GRID));
    backend.infer(&req).expect("infer")
}

fn assert_rows(out: &BinaryTensorPacket, expect: &[[f32; 6]]) {
    assert_eq!(out.dtype, TensorDtype::Float32);
    assert_eq!(out.shape, vec![expect.len() as i64, 6]);
    let got = to_f32(out);
    for (i, want) in expect.iter().enumerate() {
        for (j, w) in want.iter().enumerate() {
            let g = got[i * 6 + j];
            assert!(
                (g - w).abs() < 1e-4,
                "row {i} col {j}: got {g}, want {w}; full output {got:?}"
            );
        }
    }
}

#[tokio::test]
async fn onnx_detect_end_to_end_decodes_thresholds_and_runs_per_class_nms() {
    let out = run(false).await;
    // [x1, y1, x2, y2, score, class], sorted by descending score.
    assert_rows(
        &out,
        &[
            [75.0, 75.0, 125.0, 125.0, 0.81, 0.0], // A
            [79.0, 75.0, 129.0, 125.0, 0.72, 1.0], // C (B suppressed, D dropped)
            [6.0, 6.0, 14.0, 14.0, 0.50, 1.0],     // F
            [190.0, 40.0, 210.0, 60.0, 0.48, 0.0], // E
        ],
    );
}

#[tokio::test]
async fn onnx_detect_end_to_end_class_agnostic_nms_also_suppresses_across_classes() {
    let out = run(true).await;
    // C overlaps A (IoU 0.85) and is now suppressed despite being another class.
    assert_rows(
        &out,
        &[
            [75.0, 75.0, 125.0, 125.0, 0.81, 0.0], // A
            [6.0, 6.0, 14.0, 14.0, 0.50, 1.0],     // F
            [190.0, 40.0, 210.0, 60.0, 0.48, 0.0], // E
        ],
    );
}
